'use strict';

function plain(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function escapeHTML(value) {
  return value.replace(/[&<>"']/g, (char) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[char]);
}

function exactObject(value, required, optional) {
  if (!plain(value)) throw new TypeError('expected plain object');
  const allowed = new Set(required.concat(optional));
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) throw new TypeError('unknown field');
  }
  for (const key of required) {
    if (typeof value[key] !== 'string') throw new TypeError('invalid field');
  }
  for (const key of optional) {
    if (key in value && typeof value[key] !== 'string') throw new TypeError('invalid field');
  }
}

function renderNotice(data) {
  if (!plain(data)) throw new TypeError('data must be a plain object');
  const allowed = new Set(['heading', 'summary', 'illustration', 'action', 'steps']);
  for (const key of Object.keys(data)) if (!allowed.has(key)) throw new TypeError('unknown field');
  for (const key of ['heading', 'summary']) {
    if (key in data && typeof data[key] !== 'string') throw new TypeError('invalid text');
  }
  if ('illustration' in data) exactObject(data.illustration, ['src', 'alt'], []);
  if ('action' in data) exactObject(data.action, ['href', 'label'], []);
  if ('steps' in data && !Array.isArray(data.steps)) throw new TypeError('steps must be an array');
  const steps = data.steps || [];
  for (const step of steps) exactObject(step, ['marker', 'title', 'text'], ['href']);

  let html = '';
  if ('heading' in data) html += `<h2>${escapeHTML(data.heading)}</h2>`;
  if ('summary' in data) html += `<p>${escapeHTML(data.summary)}</p>`;
  if ('illustration' in data) html += `<img src="${escapeHTML(data.illustration.src)}" alt="${escapeHTML(data.illustration.alt)}">`;
  if ('action' in data) html += `<a href="${escapeHTML(data.action.href)}">${data.action.label}</a>`;
  if ('steps' in data) {
    html += '<ol>';
    for (const step of steps) {
      const body = 'href' in step
        ? `<p><a href="${escapeHTML(step.href)}">${escapeHTML(step.text)}</a></p>`
        : `<p>${escapeHTML(step.text)}</p>`;
      html += `<li><span>${escapeHTML(step.marker)}</span><strong>${escapeHTML(step.title)}</strong>${body}</li>`;
    }
    html += '</ol>';
  }
  return html;
}

module.exports = { renderNotice };

