'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['renderNotice']);
const { renderNotice } = api;
const typeError = fn => assert.throws(fn, TypeError);

const data = {
  heading: 'A&B <C> "D" \'E\'',
  summary: '',
  illustration: { src: 'x?a=1&b="2"', alt: '<image>' },
  action: { href: '/go?q=\'x\'', label: 'Go >' },
  steps: [
    { marker: '1&', title: 'First', text: '<do>' },
    { marker: '', title: 'Second "', text: 'click & go', href: '/a?x=1&y=2' }
  ]
};
const snapshot = JSON.parse(JSON.stringify(data));
assert.strictEqual(renderNotice(data), '<h2>A&amp;B &lt;C&gt; &quot;D&quot; &#39;E&#39;</h2><p></p><img src="x?a=1&amp;b=&quot;2&quot;" alt="&lt;image&gt;"><a href="/go?q=&#39;x&#39;">Go &gt;</a><ol><li><span>1&amp;</span><strong>First</strong><p>&lt;do&gt;</p></li><li><span></span><strong>Second &quot;</strong><p><a href="/a?x=1&amp;y=2">click &amp; go</a></p></li></ol>');
assert.deepStrictEqual(data, snapshot);
assert.strictEqual(renderNotice({}), '');
assert.strictEqual(renderNotice({ heading: '', summary: '', steps: [] }), '<h2></h2><p></p><ol></ol>');
assert.strictEqual(renderNotice({ action: { href: '', label: '' }, illustration: { src: '', alt: '' } }), '<img src="" alt=""><a href=""></a>');

typeError(() => renderNotice(null));
typeError(() => renderNotice([]));
typeError(() => renderNotice({ extra: '' }));
typeError(() => renderNotice({ heading: 1 }));
typeError(() => renderNotice({ illustration: { src: 'x' } }));
typeError(() => renderNotice({ illustration: { src: 'x', alt: 'a', title: 't' } }));
typeError(() => renderNotice({ action: { href: 1, label: 'x' } }));
typeError(() => renderNotice({ steps: {} }));
typeError(() => renderNotice({ steps: [{ marker: '1', title: 'T', text: 2 }] }));
typeError(() => renderNotice({ steps: [{ marker: '1', title: 'T', text: 'x', href: 'h', extra: '' }] }));

